workedExamples.solution_text:
Start at the origin for each point. Move horizontally first, then vertically.

$P$: $3$ units right, then $2$ units up.

$Q$: $2$ units left, then $2$ units up.

$R$: $2$ units left, then $1$ unit down.

$S$: $3$ units right, then $1$ unit down.
[tikz]
\begin{tikzpicture}[x=6mm,y=6mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{solutionblue}{HTML}{268CFF}
\draw[color=black!20,very thin,xstep=6mm,ystep=6mm] (-4,-4) grid (4,4);
\draw[<->,black] (-4.5,0)--(4.5,0) node[right] {$x$};
\draw[<->,black] (0,-4.5)--(0,4.5) node[above] {$y$};
\foreach \n in {-4,-3,-2,-1,1,2,3,4}{\path (\n,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\n$};\path (0,\n) node[left,font=\fontsize{8.5}{10}\selectfont] {$\n$};}
\path (0,0) node[below left,font=\fontsize{8.5}{10}\selectfont] {$0$};
\draw[solutionblue,dashed,->] (0,0)--(3,0)--(3,2);
\draw[solutionblue,dashed,->] (0,0)--(-2,0)--(-2,2);
\draw[solutionblue,dashed,->] (-2,0)--(-2,-1);
\draw[solutionblue,dashed,->] (3,0)--(3,-1);
\foreach \p in {(3,2),(-2,2),(-2,-1),(3,-1)}{\fill[solutionblue] \p circle (1.5pt);}
\path (3,2) node[above right] {$P$};
\path (-2,2) node[above left] {$Q$};
\path (-2,-1) node[below left] {$R$};
\path (3,-1) node[below right] {$S$};
\end{tikzpicture}
[/tikz]

